<script setup lang="ts">
import {ref,nextTick,onBeforeUnmount,onDeactivated,watch} from 'vue'
import {useHysRootAttrs} from '../../config'
import {registerOverlay} from '../../composables/overlayManager'
const props=defineProps<{items:{label:string;value:string;disabled?:boolean;type?:'item'|'divider'}[];disabled?:boolean}>(),emit=defineEmits<{select:[value:string]}>(),hysRootAttrs=useHysRootAttrs(),open=ref(false),x=ref(8),y=ref(8),panel=ref<HTMLElement>()
let unregister:(()=>void)|undefined,isTop:(()=>boolean)|undefined,previous:HTMLElement|undefined
function hide(restore=false){open.value=false;unregister?.();unregister=undefined;document.removeEventListener('pointerdown',outside,true);document.removeEventListener('keydown',escape,true);if(restore&&previous?.isConnected)previous.focus()}
function outside(event:PointerEvent){if(!panel.value?.contains(event.target as Node))hide()}
function escape(event:KeyboardEvent){if(event.key==='Escape'&&isTop?.()){event.preventDefault();event.stopImmediatePropagation();hide(true)}}
async function show(event:MouseEvent|KeyboardEvent){if(props.disabled)return;event.preventDefault();hide();previous=document.activeElement as HTMLElement;const bounds=(event.currentTarget as HTMLElement).getBoundingClientRect();x.value=event instanceof MouseEvent?event.clientX:bounds.left;y.value=event instanceof MouseEvent?event.clientY:bounds.bottom;open.value=true;const entry=registerOverlay('floating',()=>hide(true));unregister=entry.unregister;isTop=entry.isTop;await nextTick();if(!open.value)return;const box=panel.value?.getBoundingClientRect();x.value=Math.max(8,Math.min(x.value,window.innerWidth-(box?.width||190)-8));y.value=Math.max(8,Math.min(y.value,window.innerHeight-(box?.height||240)-8));panel.value?.querySelector<HTMLElement>('[role="menuitem"]:not(:disabled)')?.focus();document.addEventListener('pointerdown',outside,true);document.addEventListener('keydown',escape,true)}
function keyboard(event:KeyboardEvent){if(!['ArrowUp','ArrowDown','Home','End'].includes(event.key))return;event.preventDefault();const buttons=Array.from(panel.value?.querySelectorAll<HTMLElement>('[role="menuitem"]:not(:disabled)')||[]),index=buttons.indexOf(document.activeElement as HTMLElement),next=event.key==='Home'?0:event.key==='End'?buttons.length-1:(index+(event.key==='ArrowUp'?-1:1)+buttons.length)%buttons.length;buttons[next]?.focus()}
watch(()=>props.disabled,v=>{if(v)hide()});onBeforeUnmount(()=>hide());onDeactivated(()=>hide())
</script>
<template><div v-bind="hysRootAttrs" :tabindex="disabled?-1:0" aria-haspopup="menu" @contextmenu="show" @keydown="($event.key==='ContextMenu'||$event.shiftKey&&$event.key==='F10')&&show($event)"><slot/></div><Teleport to="body"><div v-if="open" ref="panel" v-bind="hysRootAttrs" class="hys-ui-ent-context" role="menu" :style="{left:x+'px',top:y+'px'}" @keydown="keyboard"><template v-for="item in items" :key="item.value"><hr v-if="item.type==='divider'" role="separator"/><button v-else type="button" role="menuitem" :disabled="item.disabled" @click.stop="emit('select',item.value);hide(true)"><slot name="item" :item="item">{{item.label}}</slot></button></template></div></Teleport></template>
